<script setup lang="ts">
import {ref,onMounted} from 'vue';import Panel from '../components/Panel.vue';import {api,run,seals,select} from '../store';import {useRouter} from 'vue-router'
const router=useRouter();const q=ref('');const category=ref('');const entries=ref<any[]>([]);const opened=ref<any>(null)
const categories=['朱文','历史','材料','制造'];async function search(){await run(async()=>{entries.value=await api('/knowledge?q='+encodeURIComponent(q.value)+'&category='+encodeURIComponent(category.value))})}onMounted(search)
</script>
<template><div class="knowledge-grid"><Panel title="检索条件" note="分类浏览 · 结构化知识"><h3 class="filter-title">知识专题</h3><div class="chips"><button class="chip" :class="{chosen:!category}" @click="category='';search()">全部</button><button v-for="c in categories" class="chip" :class="{chosen:category===c}" :key="c" @click="category=c;search()">{{c}}</button></div><h3 class="filter-title">印文形式</h3><p class="hint">朱文 / 白文由人工校核后用于三维设计。</p><h3 class="filter-title">数据来源</h3><div class="chips"><span class="chip">公开文献</span><span class="chip">项目算法说明</span><span class="chip">用户上传</span></div><button class="primary full" @click="search">应用筛选</button><p class="hint">当前为有来源的基础知识与实际印谱档案。未建立历史文物样本库；卡片配图为参考设计素材。</p></Panel><Panel title="数字印谱资源库" note="古印图像 · 印文释读 · 溯源文献"><form class="search-row" @submit.prevent="search"><input v-model="q" placeholder="搜索印文、形制、材质、释文与来源线索" aria-label="知识库搜索"><button class="primary">搜索知识库</button></form><div class="knowledge-cards"><button class="knowledge-card" v-for="e in entries" :key="e.id" @click="opened=e"><img :src="e.image" :alt="e.image_provenance"><h3>{{e.title}}</h3><small>{{e.category}} · {{e.source_title}}</small></button><button class="knowledge-card" v-for="s in seals.filter(s=>!category&&(!q||s.title.includes(q)))" :key="s.id" @click="select(s.id);router.push('/recognition')"><img :src="s.original_url" :alt="s.title"><h3>{{s.title}}</h3><small>{{s.source_kind==='synthetic_test'?'合成测试样本':'用户上传'}} · 实际数据库档案</small></button></div><p v-if="!entries.length" class="hint">没有匹配的知识条目。</p></Panel></div><div v-if="opened" class="modal-backdrop" @click.self="opened=null"><section class="modal" role="dialog" aria-modal="true" :aria-label="opened.title"><h2>{{opened.title}}</h2><p>{{opened.content}}</p><a v-if="opened.source_url" :href="opened.source_url" target="_blank" rel="noopener">来源：{{opened.source_title}} ↗</a><p v-else>来源：{{opened.source_title}}</p><p class="hint">配图为用户提供的设计素材，不作为文物学证据。</p><button @click="opened=null">关闭</button></section></div></template>
